interface Trackable {
    void pingLocation();
}

// Hierarchy 1: Logistics Shipping
class CargoContainer implements Trackable {
    private String containerCode;
    public CargoContainer(String code) { this.containerCode = code; }
    @Override
    public void pingLocation() {
        System.out.println("Container [" + containerCode + "] GPS coordinates: 37.7749 N, 122.4194 W");
    }
}

// Hierarchy 2: Endangered Wildlife Management
class WildWolf implements Trackable {
    private int wolfTagId;
    public WildWolf(int tagId) { this.wolfTagId = tagId; }
    @Override
    public void pingLocation() {
        System.out.println("Radio Collar #" + wolfTagId + " telemetry beacon pinging from Yellowstone Sector 4");
    }
}

public class TrackingFleetApp {
    public static void main(String[] args) {
        // Heterogeneous collection of completely unrelated objects sharing an interface!
        Trackable[] fleet = new Trackable[] {
            new CargoContainer("MSCU-908122"),
            new WildWolf(402)
        };

        for (Trackable item : fleet) {
            item.pingLocation();
        }
    }
}

