interface Cache {
    void put(String key, String value);
    String get(String key);
}

class MemoryCache implements Cache {
    private java.util.Map<String, String> map = new java.util.HashMap<>();

    // BUG: Missing public! Package-private narrows implicit public from interface
    void put(String key, String value) {
        map.put(key, value);
    }

    // BUG: Missing public!
    String get(String key) {
        return map.get(key);
    }
}

public class CacheBugApp {
    public static void main(String[] args) {
        Cache cache = new MemoryCache();
        cache.put("token", "xyz123");
        System.out.println("Cached: " + cache.get("token"));
    }
}

