interface Readable {
    String read();
}

interface Writable extends Readable {
    void write(String data);
}

class MemoryStorage implements Writable {
    private String storage = "";
    @Override
    public void write(String data) {
        this.storage = data;
        System.out.println("Written: " + data);
    }
    @Override
    public String read() {
        return storage;
    }
}

public class StorageApp {
    public static void main(String[] args) {
        Writable storage = new MemoryStorage();
        storage.write("System Config Payload");
        System.out.println("Read back: " + storage.read());
    }
}
